  # <%= admin_icon(:grid) %>, or admin_icon(:refresh, class: "spin"). Icons are decoration: the words next to them
  # carry the meaning, so they are hidden from screen readers. A name that does not exist is an error.
  def admin_icon(name, **options)
    shape = ICONS.fetch(name) { raise ArgumentError, "No icon named #{name.inspect}" }

    tag.svg(shape.html_safe, class: [ "icon", options[:class] ].compact.join(" "), viewBox: "0 0 24 24", width: 18, height: 18,
                             fill: "none", stroke: "currentColor", "stroke-width": 2, "stroke-linecap": "round",
                             "stroke-linejoin": "round", "aria-hidden": "true")
  end
end
